-- Create module_records table for generic module data persistence.
-- Any ssetunnel module can store structured records (JSONB) through the
-- control tunnel without direct database access.
CREATE TABLE "public"."module_records" (
    "id"         bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "module_id"  text NOT NULL,
    "record_id"  text NOT NULL,
    "data"       jsonb NOT NULL DEFAULT '{}',
    "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id"),
    CONSTRAINT "module_records_module_record_uniq" UNIQUE ("module_id", "record_id")
);

-- Index for listing records by module.
CREATE INDEX "module_records_module_id_idx" ON "public"."module_records" ("module_id");
